"""Synthetic Modal client fixture. It never claims to validate intelligibility."""

import io
import math
import struct
import wave
from backend.speech_contract import BASE_MODEL, LocalTTSError, PRESET_MODEL, duration_budget
from modal_service.narration import narrate


class MockQwenEngine:
    gpu_name = "Mock NVIDIA GPU (test fixture)"
    vram_mb = 12288
    cuda_graphs = True
    load_seconds = 0
    warmup_seconds = 0
    # Texts generated by narrate(), and chunk positions forced to fail once.
    generated = []
    fail_once = set()

    def __init__(self, *args):
        pass

    def synthesize(self, payload, *, call_id=None, on_started=None, progress=None):
        text = payload["text"]
        if progress:
            progress("generating_audio")
        budget = duration_budget(text, payload["preview"])
        seconds = max(budget["min_seconds"] + 0.1, min(budget["expected_seconds"], budget["max_seconds"] - 1))
        buffer = io.BytesIO()
        with wave.open(buffer, "wb") as wav:
            wav.setparams((1, 2, 24000, 0, "NONE", "not compressed"))
            wav.writeframes(
                b"".join(
                    struct.pack("<h", int(6000 * math.sin(i * 2 * math.pi * 220 / 24000)))
                    for i in range(int(seconds * 24000))
                )
            )
        return {
            "ok": True,
            "wav": buffer.getvalue(),
            "model": BASE_MODEL if payload["voice_type"] == "cloned" else PRESET_MODEL,
            "metrics": {
                "audio_seconds": seconds,
                "peak_vram_mb": 123,
                "sample_rate": 24000,
                "cuda_graphs": True,
                "gpu_execution_seconds": 0.1,
                "billable_seconds": 0.1,
                "modal_gpu": "L4",
            },
        }

    def narrate(self, payload, *, call_id=None, on_started=None, progress=None):
        mock = self

        class Container:
            model_id = BASE_MODEL if payload["voice_type"] == "cloned" else PRESET_MODEL

            def synthesize(self, text, language, *, reference, ref_text, speaker, **options):
                position = len(MockQwenEngine.generated)
                if position in MockQwenEngine.fail_once:
                    MockQwenEngine.fail_once.discard(position)
                    raise LocalTTSError("Suspicious silence after three attempts")
                MockQwenEngine.generated.append(text)
                result = mock.synthesize(
                    {"text": text, "voice_type": payload["voice_type"], "preview": False}
                )
                return result["wav"], result["metrics"]

        report = (lambda update: progress(update["stage"], update)) if progress else None
        result = narrate(Container(), payload, report)
        result["metrics"].update(
            gpu_execution_seconds=0.1, billable_seconds=0.1, modal_gpu="L4", cuda_graphs=True
        )
        return result
